import re
xml = open('xl/worksheets/sheet2.xml').read()
rows = {}
for m in re.finditer(r'<row r="([0-9]+)"[^>]*>(.*?)</row>', xml, re.S):
    r = int(m.group(1))
    content = m.group(2)
    cells = {}
    for cm in re.finditer(r'<c r="([A-Z]+[0-9]+)"([^>]*?)(?:>(.*?)</c>|/>)', content, re.S):
        ref = cm.group(1)
        attrs = cm.group(2)
        body = cm.group(3)
        cells[ref] = (attrs, body)
    rows[r] = cells

# print only rows that have more than the standard A,B,C,D,F cells
for r in sorted(rows):
    cells = rows[r]
    if any(ref[0] not in 'ABCDF' for ref in cells):
        print('ROW', r, sorted(cells.keys()))
